  def numbers_start_at_one(board)
    # slg: todo/tests/scenarios.slg:9:3 todo.tests.scenarios.numbers_start_at_one body.stmt[0]
    assert_equal(
      Runtime.claim(Todo::Model::TaskNo, 1),
      board.call { |world| Todo::Board.add(world, title: Runtime.claim(Todo::Model::Title, "milk")) }
    )
    # slg: todo/tests/scenarios.slg:10:3 todo.tests.scenarios.numbers_start_at_one body.stmt[1]
    assert_equal(
      Runtime.claim(Todo::Model::TaskNo, 2),
      board.call do |world|
        Todo::Board.add(
          world,
          title: Runtime.claim(Todo::Model::Title, "bread"),
          tags: Set[Runtime.claim(Todo::Model::Tag, "shop"), Runtime.claim(Todo::Model::Tag, "home")].freeze
        )
      end
    )
    # slg: todo/tests/scenarios.slg:11:3 todo.tests.scenarios.numbers_start_at_one body.stmt[2]
    assert_equal("added 1\nadded 2\n", board.out_text)
  end

